function thirty(){return 31}
function worldToScreen(x,y){const camX=clamp(player.x-cw/2,0,W-cw),camY=clamp(player.y-ch/2,0,H-ch);return{x:x-camX,y:y-camY}}
function drawGround(){ctx.fillStyle='#283c3a';ctx.fillRect(0,0,W,H);ctx.save();ctx.beginPath();ctx.rect(0,0,W,H);ctx.clip();
// Biome fields
ctx.fillStyle='#34494c';ctx.beginPath();ctx.ellipse(340,300,720,620,-.12,0,PI*2);ctx.fill();ctx.fillStyle='#48564b';ctx.beginPath();ctx.ellipse(2170,300,620,510,.12,0,PI*2);ctx.fill();ctx.fillStyle='#675a43';ctx.beginPath();ctx.ellipse(380,1500,780,650,-.12,0,PI*2);ctx.fill();ctx.fillStyle='#536048';ctx.beginPath();ctx.ellipse(1520,1480,940,530,.1,0,PI*2);ctx.fill();ctx.fillStyle='#344b47';ctx.beginPath();ctx.ellipse(2150,1530,550,480,0,0,PI*2);ctx.fill();
// soft terrain flecks
for(let i=0;i<130;i++){let x=(i*331+141)%W,y=(i*197+55)%H;ctx.fillStyle=i%3===0?'#dce4c20b':'#06131912';ctx.beginPath();ctx.ellipse(x,y,rand(24,70),rand(8,24),rand(0,PI),0,PI*2);ctx.fill()}
// water channels
ctx.strokeStyle='#64a4a7';ctx.lineWidth=44;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-50,680);ctx.bezierCurveTo(340,760,600,660,860,790);ctx.bezierCurveTo(1050,900,1080,1130,1360,1120);ctx.bezierCurveTo(1690,1110,1740,870,2010,930);ctx.bezierCurveTo(2200,970,2360,1200,2660,1110);ctx.stroke();ctx.strokeStyle='#8fd5d044';ctx.lineWidth=4;ctx.stroke();
// roads
ctx.strokeStyle='#d5bc8a45';ctx.lineWidth=17;ctx.beginPath();ctx.moveTo(420,420);ctx.lineTo(800,650);ctx.lineTo(1300,880);ctx.lineTo(1740,910);ctx.lineTo(1960,1220);ctx.lineTo(1100,1550);ctx.stroke();ctx.strokeStyle='#e3d3ad33';ctx.lineWidth=2;ctx.setLineDash([12,12]);ctx.stroke();ctx.setLineDash([]);
// POI grounds
for(const p of poi){ctx.fillStyle=p.kind==='bastion'?'#9dbbc21c':p.kind==='quarry'?'#ddbb8022':'#dfd2ad14';ctx.beginPath();ctx.ellipse(p.x,p.y,p.kind==='town'?205:155,p.kind==='town'?155:115,-.12,0,PI*2);ctx.fill();drawPoi(p)}
// world border
ctx.strokeStyle='#b9e8e853';ctx.lineWidth=5;ctx.strokeRect(4,4,W-8,H-8);ctx.restore()}
function drawPoi(p){ctx.save();ctx.translate(p.x,p.y);let colors={castle:'#9cabb6',bastion:'#b9dbe6',town:'#d6ae7f',quarry:'#bea477',split:'#b7afa0',labs:'#89d8d1',farm:'#c3b967',shore:'#d1a26d'};
if(p.kind==='castle'){for(let i=0;i<5;i++){let x=(i-2)*38;ctx.fillStyle='#596c70';ctx.fillRect(x-13,-28-Math.sin(i*2)*8,27,64);ctx.fillStyle='#a5bbc0';ctx.fillRect(x-11,-32-Math.sin(i*2)*8,23,9)}ctx.fillStyle='#879a9d';ctx.fillRect(-75,30,150,16)}
else if(p.kind==='bastion'){for(let i=0;i<5;i++){let x=(i%3)*36-52,y=Math.floor(i/3)*40-15;ctx.fillStyle='#879fa7';ctx.fillRect(x,y,28,30);ctx.fillStyle='#d4e5e8';ctx.fillRect(x+5,y+5,6,6)}}
else if(p.kind==='quarry'){ctx.fillStyle='#806f55';for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse((i-1.5)*39,Math.sin(i*2)*24,46,19,0,0,PI*2);ctx.fill();ctx.strokeStyle='#b6a17d';ctx.lineWidth=3;ctx.stroke()}}
else{for(let i=0;i<8;i++){let x=(i%4)*34-52,y=Math.floor(i/4)*34-18;let col=colors[p.kind];ctx.fillStyle=col+'99';ctx.fillRect(x,y,25,24);ctx.fillStyle='#f0d7a5';ctx.fillRect(x+5,y+5,5,5);ctx.fillRect(x+15,y+5,5,5)}}
ctx.fillStyle='#eaf2e8';ctx.font='700 13px "Barlow Condensed",sans-serif';ctx.textAlign='center';ctx.shadowColor='#182426';ctx.shadowBlur=5;ctx.fillText(p.name,0,67);ctx.fillStyle='#b5c3c0';ctx.font='9px "DM Sans",sans-serif';ctx.fillText(p.sub,0,80);ctx.restore()}
function drawProps(){for(const o of props){if(o.x<0||o.y<0)continue;ctx.save();ctx.translate(o.x,o.y);if(o.type==='tree'){ctx.fillStyle='#10231e66';ctx.beginPath();ctx.ellipse(3,8,o.r*.95,o.r*.53,0,0,PI*2);ctx.fill();ctx.fillStyle=o.snow?'#526a70':'#1f3b32';ctx.beginPath();ctx.arc(0,0,o.r,0,PI*2);ctx.fill();ctx.fillStyle=o.snow?'#a6bdc2':'#315746';ctx.beginPath();ctx.arc(-o.r*.22,-o.r*.24,o.r*.67,0,PI*2);ctx.fill();ctx.fillStyle=o.snow?'#d8e6e5':'#4c7656';ctx.beginPath();ctx.arc(-o.r*.34,-o.r*.36,o.r*.28,0,PI*2);ctx.fill()}
else if(o.type==='rock'){ctx.fillStyle='#152425';ctx.beginPath();ctx.ellipse(2,5,o.r,o.r*.63,0,0,PI*2);ctx.fill();ctx.fillStyle=o.snow?'#9caeae':'#6d7565';ctx.beginPath();ctx.moveTo(-o.r,-2);ctx.lineTo(-o.r*.3,-o.r*.7);ctx.lineTo(o.r*.7,-o.r*.5);ctx.lineTo(o.r,o.r*.25);ctx.lineTo(-o.r*.35,o.r*.5);ctx.closePath();ctx.fill()}
else{ctx.fillStyle='#0d1b20aa';ctx.fillRect(-o.r+3,-o.r+5,o.r*2,o.r*1.6);ctx.fillStyle=o.snow?'#a3bcc5':(o.color||'#9c8464');ctx.fillRect(-o.r,-o.r,o.r*2,o.r*1.55);ctx.fillStyle='#283f4a';ctx.fillRect(-o.r*.68,-o.r*.67,o.r*.48,o.r*.42);ctx.fillRect(o.r*.15,-o.r*.67,o.r*.48,o.r*.42);ctx.fillStyle='#dbc991';ctx.fillRect(-o.r*.6,o.r*.25,o.r*.3,o.r*.34);ctx.strokeStyle='#ffffff33';ctx.lineWidth=2;ctx.strokeRect(-o.r,-o.r,o.r*2,o.r*1.55)}ctx.restore()}}
function drawZone(){ctx.save();ctx.fillStyle='rgba(78,128,203,.18)';ctx.beginPath();ctx.rect(0,0,W,H);ctx.arc(zone.x,zone.y,zone.r,0,PI*2,true);ctx.fill('evenodd');ctx.strokeStyle='#9deaff';ctx.lineWidth=4;ctx.shadowColor='#7ee9ff';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(zone.x,zone.y,zone.r,0,PI*2);ctx.stroke();ctx.restore()}
function drawLoot(){for(const l of loot){ctx.save();ctx.translate(l.x,l.y);ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(0,8,13,6,0,0,PI*2);ctx.fill();let col=l.kind==='weapon'?'#b57bff':l.kind==='shield'?'#54caff':l.kind==='med'?'#f77a72':'#f1bd61';ctx.fillStyle=col;ctx.shadowColor=col;ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(10,0);ctx.lineTo(0,10);ctx.lineTo(-10,0);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText(l.kind==='weapon'?'✦':l.kind==='shield'?'⬡':l.kind==='med'?'✚':'▰',0,4);ctx.restore()}}
function drawCharacters(){for(const b of bots){if(b.dead)continue;drawFighter(b,false)}if(player)drawFighter(player,true)}
function drawFighter(o,isPlayer){ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.angle);ctx.fillStyle='#07121980';ctx.beginPath();ctx.ellipse(0,7,17,11,0,0,PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#42c6dd':'#da795c';ctx.beginPath();ctx.arc(0,0,12,0,PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#b5f6f7':'#ffc5a4';ctx.beginPath();ctx.arc(5,-3,7,0,PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#29445a':'#553b41';ctx.fillRect(6,-6,11,5);ctx.fillStyle='#202e38';ctx.fillRect(-5,7,11,5);ctx.restore();if(o.shield>0){ctx.strokeStyle=isPlayer?'#8ce9ff':'#f2ae83';ctx.globalAlpha=.4;ctx.lineWidth=2;ctx.beginPath();ctx.arc(o.x,o.y,17,-PI*.75,PI*.75);ctx.stroke();ctx.globalAlpha=1}if(!isPlayer&&dist(o,player)<260){ctx.fillStyle='#1b2730';ctx.fillRect(o.x-16,o.y-24,32,4);ctx.fillStyle='#ff7770';ctx.fillRect(o.x-16,o.y-24,32*o.hp/100,4)}}
function drawBullets(){for(const b of bullets){ctx.fillStyle=b.color;ctx.shadowColor=b.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(b.x,b.y,b.r||3,0,PI*2);ctx.fill();ctx.shadowBlur=0}}
function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;if(p.life<=0){particles.splice(i,1);continue}ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,PI*2);ctx.fill()}ctx.globalAlpha=1}
function draw(){if(!player)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#253a3a';ctx.fillRect(0,0,cw,ch);let camX=clamp(player.x-cw/2,0,W-cw),camY=clamp(player.y-ch/2,0,H-ch);ctx.save();ctx.translate(-camX+(shake?rand(-shake,shake):0),-camY+(shake?rand(-shake,shake):0));drawGround();drawProps();drawLoot();drawZone();drawBullets();drawCharacters();drawParticles(.016);ctx.restore();drawMini();}

