function draw(){if(!player)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#253a3a';ctx.fillRect(0,0,cw,ch);let camX=clamp(player.x-cw/2,0,W-cw),camY=clamp(player.y-ch/2,0,H-ch);ctx.save();ctx.translate(-camX+(shake?rand(-shake,shake):0),-camY+(shake?rand(-shake,shake):0));drawGround();drawProps();drawLoot();drawZone();drawBullets();drawCharacters();drawParticles(.016);ctx.restore();drawMini();}
function drawMini(){if(!player)return;let s=mini.width/W;mctx.clearRect(0,0,mini.width,mini.height);mctx.fillStyle='#31464a';mctx.fillRect(0,0,mini.width,mini.height);for(const p of poi){mctx.fillStyle='#d5c89c';mctx.beginPath();mctx.arc(p.x*s,p.y*s,2.4,0,PI*2);mctx.fill()}mctx.fillStyle='#6fb9ba';mctx.beginPath();mctx.ellipse(950*s,930*s,590*s,35*s,-.2,0,PI*2);mctx.fill();mctx.strokeStyle='#a5edff';mctx.lineWidth=2;mctx.beginPath();mctx.arc(zone.x*s,zone.y*s,zone.r*s,0,PI*2);mctx.stroke();for(const b of bots)if(!b.dead){mctx.fillStyle='#ff8d72';mctx.fillRect(b.x*s-1,b.y*s-1,3,3)}mctx.fillStyle='#a8f4ff';mctx.beginPath();mctx.arc(player.x*s,player.y*s,4,0,PI*2);mctx.fill();mctx.strokeStyle='#fff';mctx.lineWidth=1;mctx.stroke()}
function addParticles(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,PI*2),sp=rand(35,180);particles.push({x,y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,life:rand(.2,.55),max:.55,size:rand(2,5),color})}}
function shoot(owner,isPlayer){let gun=isPlayer?player.items[player.weapon]:weapons[owner.weapon],a=owner.angle;if(gun.name==='Shockwave Hammer'){if(owner.dashCD>0)return;owner.dashCD=3.5;owner.dash=.34;owner.boost=670;for(const b of bots)if(!b.dead&&dist(b,player)<125)hit(b,gun.damage,'player');addParticles(owner.x,owner.y,'#d390ff',22);shake=7;return}if(isPlayer){if(gun.ammo<=0){reload();say('MAGAZINE EMPTY · <em>R TO RELOAD</em>');return}gun.ammo--;owner.fire=gun.rate}else owner.fire=gun.rate+rand(0,.15);let pellets=gun.pellets||1;for(let i=0;i<pellets;i++){let dir=a+rand(-gun.spread,gun.spread);bullets.push({x:owner.x+Math.cos(dir)*18,y:owner.y+Math.sin(dir)*18,vx:Math.cos(dir)*gun.speed*60,vy:Math.sin(dir)*gun.speed*60,life:gun.range/(gun.speed*60),damage:gun.damage,color:isPlayer?'#b9f4ff':'#ff9679',from:isPlayer?'player':'bot',r:gun.pellets?2.3:3})}if(isPlayer&&gun.ammo===0&&gun.reserve>0)setTimeout(()=>{if(playing&&player.items[player.weapon].ammo===0)reload()},180)}
function hit(target,damage,from){let left=damage;if(target.shield>0){let take=Math.min(target.shield,left);target.shield-=take;left-=take}if(left>0)target.hp-=left;addParticles(target.x,target.y,target.shield>0?'#64d6ff':'#ff8b6c',4);if(target.hp<=0&&!target.dead){target.dead=true;if(target===player){finish(false);return}if(from==='player'){kills++;mats+=25;say(`ELIMINATED <em>${target.name}</em> · +25 MATERIALS`);for(let i=0;i<3;i++)loot.push({x:target.x+rand(-20,20),y:target.y+rand(-20,20),kind:['ammo','shield','med'][i],value:.5});updateHud()}}}
function reload(){let w=player.items[player.weapon];if(w.mag===0||w.ammo>=w.mag||w.reserve<=0||player.reloading)return;player.reloading=w.name.includes('Shotgun')?.82:1.35;say('RELOADING <em>'+w.name.toUpperCase()+'</em>')}
function pickup(){let i=loot.findIndex(l=>dist(player,l)<48);if(i<0){let nearest=props.find(p=>p.type==='building'&&dist(player,p)<95);if(nearest){mats+=12;nearest.x=-100;addParticles(player.x,player.y,'#e7c780',10);say('SALVAGED STRUCTURE · <em>+12 MATERIALS</em>');updateHud()}return}let l=loot.splice(i,1)[0];if(l.kind==='ammo'){for(const w of player.items)if(w.mag)w.reserve+=w.name.includes('Shotgun')?6:20;say('AMMO PICKED UP · <em>+20</em>')}else if(l.kind==='shield'){player.shield=Math.min(100,player.shield+25);say('SHIELD CELL · <em>OVERSHIELD RESTORED</em>')}else if(l.kind==='med'){player.hp=Math.min(100,player.hp+30);say('FIELD DRESSING · <em>VITALITY RESTORED</em>')}else{let slot=1+Math.floor(Math.random()*4);player.weapon=slot;say(`RARE CACHE · <em>${player.items[slot].name.toUpperCase()}</em>`)}updateHud()}
function say(text){let el=$('toast');el.innerHTML=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateHud(){if(!player)return;$('kills').textContent=String(kills).padStart(2,'0');$('alive').textContent=String(bots.filter(b=>!b.dead).length+1).padStart(2,'0');$('hpText').textContent=Math.ceil(player.hp);$('shieldText').textContent=Math.ceil(player.shield);$('hpBar').style.width=player.hp+'%';$('shieldBar').style.width=player.shield+'%';$('mats').textContent=mats;let w=player.items[player.weapon];$('weaponName').textContent=w.name.toUpperCase();$('inventory').innerHTML=player.items.map((g,i)=>`<div class="slot ${i===player.weapon?'active':''}"><span class="key">${i+1}</span><span class="icon">${weapons[i].icon}</span><span class="ammo">${g.mag?`${g.ammo}<small style="color:#92a4b1">/${g.reserve}</small>`:'∞'}</span><i class="rarity"></i></div>`).join('')}

